    stream_track: {
        parameters: {
            query?: {
                /** @description Expiration of a signed streamUrl (Unix timestamp); part of the URL, not to be built by hand */
                _expiration?: number;
                /** @description Signature of a signed streamUrl; part of the URL, not to be built by hand */
                _hash?: string;
            };
            header?: {
                /** @description Byte range to return, e.g. "bytes=0-1023" */
                Range?: string;
            };
            path: {
                /** @description Track identifier */
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The whole audio file */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "audio/flac": string;
                    "audio/mpeg": string;
                };
            };
            /** @description The byte range asked for in the Range header */
            206: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "audio/flac": string;
                    "audio/mpeg": string;
                };
            };
            /** @description Neither a valid JWT nor a valid, unexpired signature */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The track does not exist, or its file is missing from the library */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The byte range asked for is outside the file */
            416: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
